API Gateway / Region Router.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(api_gateway_region_router, "API Gateway / Region Router") {
    Component(Geo_DNS_and_Anycast_IP_Router, "Geo-DNS and Anycast IP Router", "Geo-DNS / Anycast IP", "Directs global traffic to regional perimeters at the network edge.")
    Component(Authorization_Middleware, "Authorization Middleware", "Internal API Gateway Middleware", "Enforces authorization checks in coordination with the Consent Management Container.")
    Component(Region_Router, "Region Router", "gRPC and REST over mTLS", "Routes traffic to regional boundaries based on patient and clinician location.")
}

Rel(Geo_DNS_and_Anycast_IP_Router, Region_Router, "Forwards global incoming traffic")
Rel(Region_Router, Authorization_Middleware, "Invokes authorization checks via internal APIs")

@enduml

Traceability Logging Container.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Traceability Logging Container container

Container_Boundary(traceability_logging_container, "Traceability Logging Container") {
    Component(OpenTelemetry_Collector_Sidecar, "OpenTelemetry Collector Sidecar", "OpenTelemetry Collector", "Decouples telemetry emission, enforces schema validation, buffering, and tail-based sampling for AI traceability.")
    Component(Telemetry_Storage_Exporter, "Telemetry Storage Exporter", "GCP Cloud Storage Exporter", "Transmits buffered telemetry data to region-isolated immutable storage sinks.")
}

Rel(OpenTelemetry_Collector_Sidecar, Telemetry_Storage_Exporter, "Forwards buffered and sampled telemetry", "")

@enduml

FHIR/E-Prescription Adapter Containers.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the FHIR/E-Prescription Adapter Containers container

Container_Boundary(fhirdb, "FHIR/E-Prescription Adapter Containers") {
    Component(US_HL7_FHIR_Adapter, "US HL7 FHIR Adapter", "Containerized Service / REST / FHIR", "Exchanges clinical data with US HL7 FHIR Providers using Anti-Corruption Layer patterns.")
    Component(EU_EPrescription_Gateway_Adapter, "EU E-Prescription Gateway Adapter", "Containerized Service / National Protocols", "Routes e-prescriptions to EU National E-Prescription Gateways with strict regional routing.")
    Component(Pharmacy_Network_Coordinator, "Pharmacy Network Coordinator", "Containerized Service / REST / HTTPS", "Coordinates fulfillment with Regional Pharmacy Networks, protected by circuit breakers and bulkheads.")
}

Rel(US_HL7_FHIR_Adapter, EU_EPrescription_Gateway_Adapter, "Coordinates cross-border clinical data mapping", "Internal gRPC")
Rel(EU_EPrescription_Gateway_Adapter, Pharmacy_Network_Coordinator, "Dispatches fulfillment requests", "Internal API")

@enduml

Event-Driven Integration Bus.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(Event_Driven_Integration_Bus, "Event-Driven Integration Bus") {
    Component(Regional_Pub_Sub_Topics, "Regional Pub/Sub Topics", "GCP Pub/Sub with Regional Topics", "Manages regional message distribution, dead-letter queues, and flow control for asynchronous event-driven communication.")
    Component(Schema_Validator, "Schema Validator", "Protocol Buffers / JSON Schema", "Enforces strict message schema validation at publisher boundaries.")
    Component(Claim_Check_Handler, "Claim Check Handler", "GCP Cloud Storage", "Offloads and retrieves large payloads using the Claim Check pattern to maintain optimal event bus performance.")
}

Rel(Regional_Pub_Sub_Topics, Schema_Validator, "Validates messages against strict schemas", "")
Rel(Regional_Pub_Sub_Topics, Claim_Check_Handler, "Offloads large payloads", "")
@enduml

Regional Caches.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Regional Caches container

Container_Boundary(regional_caches, "Regional Caches") {
    Component(MemorystoreInstance, "Memorystore Instance", "GCP Memorystore", "Provides low-latency regional caching supporting the Cache-Aside pattern, TTLs, and Redlock distributed locks.")
